//! AAC helpers

/// A silent AAC-LC raw data block for one channel (a single SCE)
///
/// Generated by the ffmpeg 8.1.3 `aac` encoder from `anullsrc` (steady-state frames, the
/// first frame's DSE dropped). The bytes do not depend on the sample rate.
pub const SILENT_AU_MONO: [u8; 4] = [0x01, 0x18, 0x20, 0x07];

/// A silent AAC-LC raw data block for two channels (a single CPE), as [`SILENT_AU_MONO`]
pub const SILENT_AU_STEREO: [u8; 6] = [0x21, 0x10, 0x04, 0x60, 0x8c, 0x1c];

/// A silent AAC-LC access unit (1024 samples) for `channels`, if one is available
///
/// Only mono and stereo are supported, which covers every camera seen so far.
pub fn silent_au(channels: u8) -> Option<&'static [u8]> {
    match channels {
        1 => Some(&SILENT_AU_MONO),
        2 => Some(&SILENT_AU_STEREO),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE_RATES: [u32; 13] = [
        96000, 88200, 64000, 48000, 44100, 32000, 24000, 22050, 16000, 12000, 11025, 8000, 7350,
    ];

    fn adts(au: &[u8], sample_rate: u32, channels: u8) -> Vec<u8> {
        let sr = SAMPLE_RATES.iter().position(|&r| r == sample_rate).unwrap() as u8;
        let len = au.len() + 7;
        let mut out = vec![
            0xff,
            0xf1,
            (1 << 6) | (sr << 2) | (channels >> 2),
            ((channels & 3) << 6) | (len >> 11) as u8,
            (len >> 3) as u8,
            ((len & 7) << 5) as u8 | 0x1f,
            0xfc,
        ];
        out.extend_from_slice(au);
        out
    }

    /// Decode `n` copies of the AU with symphonia and return the decoded samples
    fn symphonia_decode(au: &[u8], sample_rate: u32, channels: u8, n: usize) -> Vec<f32> {
        use symphonia::core::audio::{Channels, SampleBuffer};
        use symphonia::core::codecs::{CodecParameters, DecoderOptions, CODEC_TYPE_AAC};
        use symphonia::core::formats::Packet;

        let mut params = CodecParameters::new();
        params
            .for_codec(CODEC_TYPE_AAC)
            .with_sample_rate(sample_rate)
            .with_channels(if channels == 1 {
                Channels::FRONT_LEFT
            } else {
                Channels::FRONT_LEFT | Channels::FRONT_RIGHT
            });
        let mut decoder = symphonia::default::get_codecs()
            .make(&params, &DecoderOptions::default())
            .unwrap();
        let mut out = vec![];
        for i in 0..n {
            let packet = Packet::new_from_slice(0, i as u64 * 1024, 1024, au);
            let decoded = decoder.decode(&packet).unwrap();
            let mut buf = SampleBuffer::<f32>::new(decoded.capacity() as u64, *decoded.spec());
            buf.copy_interleaved_ref(decoded);
            out.extend_from_slice(buf.samples());
        }
        out
    }

    #[test]
    fn test_silent_au_symphonia() {
        for channels in [1u8, 2] {
            for sample_rate in [8000, 16000, 48000] {
                let samples =
                    symphonia_decode(silent_au(channels).unwrap(), sample_rate, channels, 20);
                assert_eq!(samples.len(), 20 * 1024 * channels as usize);
                assert!(
                    samples.iter().all(|&s| s == 0.0),
                    "{} ch @ {} Hz decodes to non-zero samples",
                    channels,
                    sample_rate
                );
            }
        }
    }

    /// Decodes with ffmpeg. Skipped when ffmpeg is missing, unless `NEOLINK_REQUIRE_FFMPEG`
    /// is set (CI sets it). `NEOLINK_FFMPEG` overrides the binary.
    #[test]
    fn test_silent_au_ffmpeg() {
        use std::io::Write;
        use std::process::{Command, Stdio};

        let ffmpeg = std::env::var("NEOLINK_FFMPEG").unwrap_or_else(|_| "ffmpeg".to_string());
        if Command::new(&ffmpeg).arg("-version").output().is_err() {
            assert!(
                std::env::var_os("NEOLINK_REQUIRE_FFMPEG").is_none(),
                "ffmpeg not found"
            );
            eprintln!("ffmpeg not found, skipping");
            return;
        }
        for channels in [1u8, 2] {
            for sample_rate in [16000, 48000] {
                let stream: Vec<u8> = (0..50)
                    .flat_map(|_| adts(silent_au(channels).unwrap(), sample_rate, channels))
                    .collect();
                let mut child = Command::new(&ffmpeg)
                    .args([
                        "-v", "error", "-f", "aac", "-i", "pipe:0", "-f", "s16le", "pipe:1",
                    ])
                    .stdin(Stdio::piped())
                    .stdout(Stdio::piped())
                    .spawn()
                    .unwrap();
                let mut stdin = child.stdin.take().unwrap();
                let writer = std::thread::spawn(move || stdin.write_all(&stream).unwrap());
                let output = child.wait_with_output().unwrap();
                writer.join().unwrap();
                assert!(output.status.success());
                assert_eq!(output.stdout.len(), 50 * 1024 * 2 * channels as usize);
                assert!(output.stdout.iter().all(|&b| b == 0));
            }
        }
    }
}
